 <div><a class="back-link" href="<?= $canManage?'/invoices':'/portal/invoices' ?>">← <?= $canManage?'Invoices':'My Invoices' ?></a><div class="eyebrow">Invoice details</div><h1><?= htmlspecialchars((string)$invoice['invoice_number']) ?></h1><p><?= htmlspecialchars((string)$customer) ?> · Due <?= date('j F Y',strtotime((string)$invoice['due_date'])) ?></p></div>
 <div class="header-actions no-print"><?php if($canManage&&in_array($invoice['status'],['draft','sent','overdue','partially_paid'],true)&&$invoice['amount_paid']==0): ?><a class="secondary-button" href="/invoices/<?= (int)$invoice['id'] ?>/edit">Edit</a><?php endif; ?><button class="secondary-button" onclick="window.print()">Print invoice</button><span class="status <?= htmlspecialchars((string)$invoice['status']) ?>"><?= htmlspecialchars(ucwords(str_replace('_',' ',(string)$invoice['status']))) ?></span></div>
</header>
