<article class="invoice-document">
 <header><div class="invoice-brand"><span class="brand-mark">V</span><div><strong>Veelox Digital</strong><small>Invoice</small></div></div><div class="invoice-number"><small>Invoice number</small><strong><?= htmlspecialchars((string)$invoice['invoice_number']) ?></strong></div></header>
 <section class="invoice-parties"><div><small>Bill to</small><strong><?= htmlspecialchars((string)$customer) ?></strong><span><?= htmlspecialchars((string)$invoice['contact_name']) ?><br><?= implode('<br>',array_map('htmlspecialchars',$address)) ?><br><?= htmlspecialchars((string)$invoice['email']) ?></span></div><dl><div><dt>Issue date</dt><dd><?= date('j F Y',strtotime((string)$invoice['issue_date'])) ?></dd></div><div><dt>Due date</dt><dd><?= date('j F Y',strtotime((string)$invoice['due_date'])) ?></dd></div><?php if($invoice['order_number']): ?><div><dt>Order</dt><dd><?= htmlspecialchars((string)$invoice['order_number']) ?></dd></div><?php endif; ?></dl></section>
 <div class="invoice-lines"><div class="line-head"><span>Description</span><span>Quantity</span><span>Unit price</span><span>Total</span></div><?php foreach($items as $item): ?><div class="line-row"><strong><?= htmlspecialchars((string)$item['description']) ?></strong><span><?= rtrim(rtrim(number_format((float)$item['quantity'],2),'0'),'.') ?></span><span>£<?= number_format($item['unit_price_amount']/100,2) ?></span><span>£<?= number_format($item['line_total_amount']/100,2) ?></span></div><?php endforeach; ?></div>
 <section class="invoice-bottom"><div><?php if($invoice['notes']): ?><small>Notes</small><p><?= nl2br(htmlspecialchars((string)$invoice['notes'])) ?></p><?php endif; ?><?php if($bank['sort_code']||$bank['account_number']): ?><small>Bank transfer details</small><p><?= htmlspecialchars((string)$bank['account_name']) ?><br><?= htmlspecialchars((string)$bank['name']) ?><br>Sort code: <?= htmlspecialchars((string)$bank['sort_code']) ?><br>Account: <?= htmlspecialchars((string)$bank['account_number']) ?><br>Reference: <?= htmlspecialchars((string)$invoice['invoice_number']) ?></p><?php endif; ?></div><dl class="invoice-totals"><div><dt>Subtotal</dt><dd>£<?= number_format($invoice['subtotal_amount']/100,2) ?></dd></div><div><dt>Paid</dt><dd>£<?= number_format($invoice['amount_paid']/100,2) ?></dd></div><div class="balance"><dt>Balance due</dt><dd>£<?= number_format($invoice['balance_due']/100,2) ?></dd></div></dl></section>
</article>
<?php if(!$canManage&&$stripeEnabled&&$invoice['balance_due']>0&&!in_array($invoice['status'],['draft','void','refunded'],true)): ?><section class="portal-payment no-print"><div><span class="eyebrow">Secure card payment</span><h2>Pay £<?= number_format($invoice['balance_due']/100,2) ?> online</h2><p>You’ll be transferred to Stripe’s secure checkout to complete your payment.</p></div><form method="post" action="/portal/invoices/<?= (int)$invoice['id'] ?>/stripe-checkout"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><button class="stripe-button" type="submit">Pay securely by card →</button></form></section><?php endif; ?>
