 <aside><?php if($invoice['balance_due']>0&&!in_array($invoice['status'],['void','refunded'],true)): ?><section class="detail-card"><div class="panel-heading"><div><span class="eyebrow">Bank transfer</span><h2>Record payment</h2></div></div><form class="payment-form" method="post" action="/invoices/<?= (int)$invoice['id'] ?>/payments"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><label>Amount (£)<input name="amount" inputmode="decimal" value="<?= number_format($invoice['balance_due']/100,2,'.','') ?>" required></label><label>Payment date<input type="date" name="paid_at" value="<?= date('Y-m-d') ?>" required></label><label>Bank reference<input name="reference" maxlength="190" placeholder="Transaction reference"></label><button class="primary-button full" type="submit">Record bank payment</button></form></section><?php endif; ?><?php if($invoice['amount_paid']==0): ?><section class="detail-card"><div class="panel-heading"><div><span class="eyebrow">Status</span><h2>Invoice workflow</h2></div></div><form method="post" action="/invoices/<?= (int)$invoice['id'] ?>/status"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><label class="status-select">Change status<select name="status"><option value="draft" <?= $invoice['status']==='draft'?'selected':'' ?>>Draft</option><option value="sent" <?= in_array($invoice['status'],['sent','overdue'],true)?'selected':'' ?>>Sent / outstanding</option><option value="void" <?= $invoice['status']==='void'?'selected':'' ?>>Void</option></select></label><button class="secondary-button full" type="submit">Update invoice</button></form></section><?php endif; ?></aside>
</div>
